async function pageFunction(context) {
  const { $, request } = context;
  const tables = [];
  $('table').each((i, el) => {
    const rows = [];
    $(el).find('tr').each((ri, tr) => {
      const cells = [];
      $(tr).find('th,td').each((ci, cell) => cells.push($(cell).text().replace(/\s+/g, ' ').trim()));
      if (cells.some(Boolean)) rows.push(cells);
    });
    if (rows.length) tables.push(rows.slice(0, 30));
  });
  return {
    url: request.url,
    title: String($('meta[property="og:title"]').attr('content') || $('h1').first().text() || '').replace(/\s+/g, ' ').trim().slice(0, 180),
    image: $('meta[property="og:image"]').attr('content') || '',
    text: $('body').text().replace(/\s+/g, ' ').trim().slice(0, 14000),
    tables
  };
}
